package com.fintrack.controller; import com.fintrack.dto.TransactionRequest; import com.fintrack.model.*; import com.fintrack.repository.TransactionRepository; import com.fintrack.service.CurrentUser; import jakarta.validation.Valid; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/transactions") public class TransactionController{private final TransactionRepository repo;private final CurrentUser current;public TransactionController(TransactionRepository r,CurrentUser c){repo=r;current=c;}@GetMapping public List<Transaction> all(Authentication a){return repo.findByUserIdOrderByTransactionDateDesc(current.get(a).getId());}@PostMapping public Transaction add(@Valid @RequestBody TransactionRequest r,Authentication a){Transaction t=new Transaction();t.setUser(current.get(a));t.setDescription(r.description());t.setCategory(r.category());t.setAmount(r.amount());t.setType(r.type());return repo.save(t);}@DeleteMapping("/{id}")public void delete(@PathVariable Long id,Authentication a){Transaction t=repo.findById(id).orElseThrow(()->new IllegalArgumentException("Transaction not found"));if(!t.getUser().getId().equals(current.get(a).getId()))throw new IllegalArgumentException("Not your transaction");repo.delete(t);}}
